-- PostgreSQL fresh-deployment baseline. Existing MySQL migration checksums are unchanged.

-- Mirrors the consolidated MySQL domain baseline; forward changes require migrations for both vendors.

CREATE EXTENSION IF NOT EXISTS citext;

CREATE TABLE "yak_dataset" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "project_id" bigint NOT NULL,
  "development_node_id" bigint,
  "name" citext NOT NULL CHECK (length("name") <= 200),
  "description" citext CHECK (length("description") <= 2000),
  "status" citext NOT NULL CHECK (length("status") <= 32),
  "current_version_id" bigint,
  "draft_data_source_id" citext CHECK (length("draft_data_source_id") <= 128),
  "draft_sql" text,
  "draft_schema_snapshot" jsonb,
  "create_time" timestamp(6) without time zone NOT NULL,
  "update_time" timestamp(6) without time zone NOT NULL,
  PRIMARY KEY ("id")
);

CREATE INDEX "yak_dataset_idx_yak_dataset_create_time" ON "yak_dataset" ("create_time");

CREATE INDEX "yak_dataset_idx_yak_dataset_current_version" ON "yak_dataset" ("current_version_id");

CREATE INDEX "yak_dataset_idx_yak_dataset_project_development_node" ON "yak_dataset" ("project_id", "development_node_id");

CREATE INDEX "yak_dataset_idx_yak_dataset_project_status_update" ON "yak_dataset" ("project_id", "status", "update_time");

CREATE INDEX "yak_dataset_idx_yak_dataset_status_update" ON "yak_dataset" ("status", "update_time");

CREATE INDEX "yak_dataset_idx_yak_dataset_update_id" ON "yak_dataset" ("update_time", "id");

CREATE UNIQUE INDEX "yak_dataset_uk_yak_dataset_development_node" ON "yak_dataset" ("development_node_id");

CREATE TABLE "yak_dataset_version" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "dataset_id" bigint NOT NULL,
  "version_no" integer NOT NULL,
  "source_type" citext NOT NULL CHECK (length("source_type") <= 32),
  "source_task_asset_id" bigint NOT NULL,
  "source_task_revision_id" bigint NOT NULL,
  "source_task_revision_no" integer NOT NULL,
  "data_source_id" citext CHECK (length("data_source_id") <= 128),
  "sql_content" text,
  "schema_snapshot" jsonb,
  "create_time" timestamp(6) without time zone NOT NULL,
  PRIMARY KEY ("id")
);

CREATE INDEX "yak_dataset_version_idx_yak_dataset_version_datasource" ON "yak_dataset_version" ("data_source_id");

CREATE INDEX "yak_dataset_version_idx_yak_dataset_version_source" ON "yak_dataset_version" ("source_task_asset_id", "source_task_revision_id");

CREATE UNIQUE INDEX "yak_dataset_version_uk_yak_dataset_version_no" ON "yak_dataset_version" ("dataset_id", "version_no");

CREATE TABLE "yak_dataset_field" (
  "field_id" citext NOT NULL CHECK (length("field_id") <= 64),
  "version_id" bigint NOT NULL,
  "physical_name" citext NOT NULL CHECK (length("physical_name") <= 128),
  "display_name" citext NOT NULL CHECK (length("display_name") <= 200),
  "data_type" citext NOT NULL CHECK (length("data_type") <= 32),
  "nullable" smallint DEFAULT 1 NOT NULL,
  "description" citext CHECK (length("description") <= 1000),
  "default_role" citext NOT NULL CHECK (length("default_role") <= 32),
  "sort_order" integer DEFAULT 0 NOT NULL,
  PRIMARY KEY ("version_id", "field_id")
);

CREATE INDEX "yak_dataset_field_idx_yak_dataset_field_role" ON "yak_dataset_field" ("version_id", "default_role");

CREATE UNIQUE INDEX "yak_dataset_field_uk_yak_dataset_field_physical_name" ON "yak_dataset_field" ("version_id", "physical_name");

CREATE TABLE "yak_dataset_draft_field" (
  "field_id" citext NOT NULL CHECK (length("field_id") <= 64),
  "dataset_id" bigint NOT NULL,
  "physical_name" citext NOT NULL CHECK (length("physical_name") <= 128),
  "display_name" citext NOT NULL CHECK (length("display_name") <= 200),
  "data_type" citext NOT NULL CHECK (length("data_type") <= 32),
  "nullable" smallint DEFAULT 1 NOT NULL,
  "description" citext CHECK (length("description") <= 1000),
  "default_role" citext NOT NULL CHECK (length("default_role") <= 32),
  "sort_order" integer DEFAULT 0 NOT NULL,
  PRIMARY KEY ("dataset_id", "field_id")
);

CREATE INDEX "yak_dataset_draft_field_idx_yak_dataset_draft_field_role" ON "yak_dataset_draft_field" ("dataset_id", "default_role");

CREATE UNIQUE INDEX "yak_dataset_draft_field_uk_yak_dataset_draft_field_phy_ef9d495a" ON "yak_dataset_draft_field" ("dataset_id", "physical_name");

CREATE TABLE "yak_dataset_query_performance" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "project_id" bigint NOT NULL,
  "query_id" citext NOT NULL CHECK (length("query_id") <= 32),
  "dataset_id" bigint NOT NULL,
  "dataset_name" citext CHECK (length("dataset_name") <= 200),
  "dataset_version_id" bigint,
  "dataset_version_no" integer,
  "source_type" citext CHECK (length("source_type") <= 32),
  "data_source_id" citext CHECK (length("data_source_id") <= 128),
  "sql_preview" citext CHECK (length("sql_preview") <= 4000),
  "sql_hash" citext CHECK (length("sql_hash") <= 64),
  "status" citext NOT NULL CHECK (length("status") <= 32),
  "failure_stage" citext CHECK (length("failure_stage") <= 64),
  "error_type" citext CHECK (length("error_type") <= 200),
  "error_message" citext CHECK (length("error_message") <= 2000),
  "subject_type" citext CHECK (length("subject_type") <= 32),
  "subject_source_domain" citext CHECK (length("subject_source_domain") <= 64),
  "subject_source_identity" citext CHECK (length("subject_source_identity") <= 255),
  "subject_display_hint" citext CHECK (length("subject_display_hint") <= 255),
  "wait_millis" bigint DEFAULT 0 NOT NULL,
  "prepare_millis" bigint DEFAULT 0 NOT NULL,
  "execute_millis" bigint DEFAULT 0 NOT NULL,
  "transfer_millis" bigint DEFAULT 0 NOT NULL,
  "total_millis" bigint DEFAULT 0 NOT NULL,
  "returned_rows" integer DEFAULT 0 NOT NULL,
  "truncated" smallint DEFAULT 0 NOT NULL,
  "started_at" timestamp(6) without time zone NOT NULL,
  "finished_at" timestamp(6) without time zone NOT NULL,
  PRIMARY KEY ("id")
);

CREATE INDEX "yak_dataset_query_performance_idx_yak_dataset_query_pe_a82a2246" ON "yak_dataset_query_performance" ("project_id", "dataset_id", "started_at", "id");

CREATE INDEX "yak_dataset_query_performance_idx_yak_dataset_query_pe_f655591c" ON "yak_dataset_query_performance" ("project_id", "started_at", "id");

CREATE INDEX "yak_dataset_query_performance_idx_yak_dataset_query_pe_5c034b43" ON "yak_dataset_query_performance" ("project_id", "sql_hash", "started_at");

CREATE INDEX "yak_dataset_query_performance_idx_yak_dataset_query_pe_594ddca8" ON "yak_dataset_query_performance" ("project_id", "status", "started_at", "id");

CREATE INDEX "yak_dataset_query_performance_idx_yak_dataset_query_pe_fab68516" ON "yak_dataset_query_performance" ("project_id", "subject_type", "subject_source_domain", "subject_source_identity", "started_at", "id");

CREATE UNIQUE INDEX "yak_dataset_query_performance_uk_yak_dataset_query_per_9eeb9375" ON "yak_dataset_query_performance" ("query_id");

CREATE TABLE "yak_dataset_source_publication_lock" (
  "project_id" bigint NOT NULL,
  "source_task_asset_id" bigint NOT NULL,
  PRIMARY KEY ("project_id", "source_task_asset_id")
);
